insert into public.audit_logs(username,action,entity_type,entity_id,details) values ('system_bootstrap','INITIALIZE_DATABASE','SYSTEM','ALL','Seeded initial 6-month historical baseline from the demo CSV datasets.');

select public._scan_alerts();
